css:
.d-table-global-search{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-table-global-search *,.d-table-global-search *::before,.d-table-global-search *::after{box-sizing:border-box}
.d-table-global-search [hidden]{display:none!important}
.d-table-global-search .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-table-global-search .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-table-global-search label{display:block;margin:8px 0}
.d-table-global-search input,.d-table-global-search select,.d-table-global-search textarea,.d-table-global-search button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-table-global-search input:not([type=checkbox]):not([type=radio]),.d-table-global-search select,.d-table-global-search textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-table-global-search button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-table-global-search button:disabled{opacity:.5;cursor:default}
.d-table-global-search :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-table-global-search [aria-invalid=true]{border-color:var(--warn)!important}
.d-table-global-search .d-scroll{max-width:100%;overflow:auto}
.d-table-global-search table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-table-global-search th,.d-table-global-search td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-table-global-search caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-table-global-search progress{width:100%;accent-color:var(--ink)}
.d-table-global-search pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-table-global-search h3,.d-table-global-search p{margin:8px 0}
.d-table-global-search [aria-pressed=true],.d-table-global-search [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-table-global-search .d-grow{flex:1;min-width:100px}
.d-table-global-search summary{cursor:pointer;padding:6px 0}
.d-table-global-search ul,.d-table-global-search ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const filter=()=>{const needle=q('[data-search]').value.trim().toLocaleLowerCase();let count=0;qa('tbody tr').forEach(row=>{row.hidden=!row.textContent.toLocaleLowerCase().includes(needle);if(!row.hidden)count++;});say(count?count+' 条匹配':'没有匹配项，请修改关键词');};q('[data-search]').oninput=filter;filter();})(root, q, qa, say);
}
